result.output:
worktree-wp-s-git-boundary
//! A checkpoint records a local command's inputs before its first write, so an interrupted run can be resumed from
//! them or undone ([ADR 13](../../../../docs/adr/0013-interrupted-version-runs-resume-from-a-checkpoint-ref.md)).

use std::path::Path;

use sha2::{Digest, Sha256};

use super::access::GitAccess;
use super::VcsError;
use crate::CommitSha;

/// Where an interrupted `callisto version` run keeps its inputs. A per-worktree ref, so a linked worktree has its own
/// checkpoint and never sees or discards another's.
pub const VERSION_CHECKPOINT: &str = "refs/worktree/callisto/checkpoint/version";

const HEAD_TRAILER: &str = "Callisto-Head";
const TAGS_TRAILER: &str = "Callisto-Tags";
const VERSION_TRAILER: &str = "Callisto-Version";
const DATE_TRAILER: &str = "Callisto-Date";
const WORKSPACE_TRAILER: &str = "Callisto-Workspace";

/// The inputs a plan reads besides files, recorded in the checkpoint commit's message.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CheckpointFacts {
    pub head: String,
    pub tags: String,
    pub callisto_version: String,
    /// The workspace directory inside the repository (empty at the top). Workspaces share a worktree's checkpoint ref,
    /// so a run in another workspace must not resume this one's.
    pub workspace: String,
}

/// A recorded checkpoint: a commit whose tree is the working tree, whose first parent is `HEAD` and whose second
/// parent records the index.
#[derive(Clone, Debug)]
pub struct Checkpoint {
    pub commit: CommitSha,
    pub facts: CheckpointFacts,
    /// The date the run planned with (`YYYY-MM-DD`), so a resume on a later day writes the same changelog dates.
    pub date: String,
}

impl GitAccess<'_> {
    /// The checkpoint at `name`, or `None` when there is none.
    pub fn checkpoint(&self, name: &str) -> Result<Option<Checkpoint>, VcsError> {
        let Some(commit) = self.resolve_commit(name)? else {
            return Ok(None);
        };
        let message = self.git_stdout(&["show", "-s", "--no-show-signature", "--format=%B", commit.as_str()])?;
        let trailer = |key: &str| {
            message
                .lines()
                .find_map(|line| line.strip_prefix(key)?.strip_prefix(": "))
                .unwrap_or_default()
                .to_string()
        };
        Ok(Some(Checkpoint {
            facts: CheckpointFacts {
                head: trailer(HEAD_TRAILER),
                tags: trailer(TAGS_TRAILER),
                callisto_version: trailer(VERSION_TRAILER),
                workspace: trailer(WORKSPACE_TRAILER),
            },
            date: trailer(DATE_TRAILER),
            commit,
        }))
    }

    /// The facts a checkpoint taken now would record.
    pub fn checkpoint_facts(&self, callisto_version: &str) -> Result<CheckpointFacts, VcsError> {
        let tags = self.git_stdout(&["for-each-ref", "--format=%(objectname) %(refname)", "refs/tags"])?;
        Ok(CheckpointFacts {
            head: self.head_sha()?.as_str().to_string(),
            tags: crate::release::digest::lower_hex(Sha256::digest(tags.as_bytes())),
            callisto_version: callisto_version.to_string(),
            workspace: self.root_prefix()?.display().to_string(),
        })
    }

    /// Records `HEAD`, the index, and the working tree under this root (untracked files included, ignored files
    /// left out) at `name`, without touching the user's index or working tree.
    ///
    /// # Errors
    ///
    /// [`VcsError::CheckpointHeld`] when `name` already exists, so two runs never share one; a failed git command
    /// otherwise.
    pub fn create_checkpoint(&self, name: &str, facts: &CheckpointFacts, date: &str) -> Result<CommitSha, VcsError> {
        let git_dir = self.git_stdout(&["rev-parse", "--absolute-git-dir"])?;
        let index = Path::new(git_dir.trim()).join("callisto-checkpoint.index");
        let index_str = index.to_string_lossy().into_owned();
        let env = [("GIT_INDEX_FILE", index_str.as_str())];
        let real_index = self.git_stdout(&["rev-parse", "--git-path", "index"])?;
        let real_index = self.root().join(real_index.trim());
        let created = (|| {
            let index_commit = self.internal_commit(&self.git_stdout(&["write-tree"])?, &[&facts.head], "index")?;
            // Seeded from the real index so Git's stat cache spares rehashing every tracked file; without one it is
            // built from `HEAD`.
            if std::fs::copy(&real_index, &index).is_err() {
                self.git_stdout_env(&["read-tree", "HEAD"], &env)?;
            }
            // A file Git cannot read, or whose line endings `core.safecrlf` objects to, is not something `version`
            // reads or writes, so it must not stop the run: it is left out of the record.
            let args = ["-c", "core.safecrlf=false", "add", "-A", "--ignore-errors", "--", "."];
            let output = self.runner().run_with_env("git", &args, self.root(), &env)?;
            if !output.success() && !output.stderr.contains("unable to index") {
                return Err(git_failed(&args, self.root(), &output.stderr));
            }
            let tree = self.git_stdout_env(&["write-tree"], &env)?;
            let message = format!(
                "callisto checkpoint\n\n{HEAD_TRAILER}: {}\n{TAGS_TRAILER}: {}\n{VERSION_TRAILER}: {}\n{WORKSPACE_TRAILER}: {}\n{DATE_TRAILER}: {date}\n",
                facts.head, facts.tags, facts.callisto_version, facts.workspace
            );
            self.internal_commit(&tree, &[&facts.head, index_commit.as_str()], &message)
        })();
        std::fs::remove_file(&index).ok();
        let commit = created?;
        let args = ["update-ref", name, commit.as_str(), ""];
        let output = self.runner().run("git", &args, self.root())?;
        if !output.success() {
            return Err(if output.stderr.contains("already exists") {
                VcsError::CheckpointHeld { name: name.to_string() }
            } else {
                git_failed(&args, self.root(), &output.stderr)
            });
        }
        Ok(commit)
    }

    /// Removes the checkpoint at `name`; removing one that does not exist is not an error.
    pub fn delete_checkpoint(&self, name: &str) -> Result<(), VcsError> {
        self.git_stdout(&["update-ref", "-d", name]).map(drop)
    }

    /// Whether `path` (relative to this root) has an entry in the index.
    pub fn is_staged(&self, path: &Path) -> Result<bool, VcsError> {
        let path = path.to_string_lossy();
        self.git_stdout(&["--literal-pathspecs", "ls-files", "--", &path])
            .map(|listed| !listed.is_empty())
    }

    /// Whether `path` (relative to this root) is on disk as `rev` recorded it, compared as Git compares: through its
    /// line-ending and attribute filters, so a checkout with CRLF endings matches the blob it was written from. Absent
    /// on both sides matches.
    pub fn path_matches_at(&self, rev: &str, path: &Path) -> Result<bool, VcsError> {
        Ok(self.blob_hash_at(rev, path)? == self.file_hash(path)?)
    }

    /// The object id of `path` (relative to this root) in `rev`'s tree, or `None` when it is absent there.
    pub fn blob_hash_at(&self, rev: &str, path: &Path) -> Result<Option<String>, VcsError> {
        if !self.path_exists_at(rev, path)? {
            return Ok(None);
        }
        let spec = format!("{rev}:./{}", path.display());
        self.git_stdout(&["rev-parse", &spec]).map(Some)
    }

    /// The object id Git would give the file at `path` (relative to this root) as it is on disk now, through its
    /// line-ending and attribute filters, or `None` when it is absent. Two ids are equal exactly when Git would
    /// store the same content.
    pub fn file_hash(&self, path: &Path) -> Result<Option<String>, VcsError> {
        let full = self.root().join(path);
        if !full.is_file() {
            return Ok(None);
        }
        let name = path.to_string_lossy();
        let file = full.to_string_lossy();
        self.git_stdout(&["hash-object", "--path", &name, &file]).map(Some)
    }

    /// Checks the checkpoint at `name` out at `dir` (which must not exist) with `HEAD` on the commit the run started
    /// from, so history reads (commit inference) see the real commits and not the checkpoint's own. The files and the
    /// index stay as the checkpoint recorded them.
    pub fn add_checkpoint_worktree(&self, name: &str, dir: &Path, head: &str) -> Result<(), VcsError> {
        // The scratch checkout is internal: none of the user's hooks run in it, and a failed step takes its
        // registration with it.
        let dir_text = dir.to_string_lossy();
        let no_hooks = ["-c", "core.hooksPath=/dev/null"];
        let add: Vec<&str> = no_hooks
            .iter()
            .copied()
            .chain(["worktree", "add", "--detach", "--quiet", &dir_text, name])
            .collect();
        self.git_stdout(&add)?;
        let reset: Vec<&str> = no_hooks
            .iter()
            .copied()
            .chain(["reset", "--quiet", "--soft", head])
            .collect();
        let output = self.runner().run("git", &reset, dir)?;
        if !output.success() {
            self.remove_worktree(dir).ok();
            return Err(git_failed(&reset, dir, &output.stderr));
        }
        Ok(())
    }

    /// This root's path inside the repository (empty at the top), so the same directory can be found in a worktree.
    pub fn root_prefix(&self) -> Result<std::path::PathBuf, VcsError> {
        self.git_stdout(&["rev-parse", "--show-prefix"])
            .map(std::path::PathBuf::from)
    }

    /// The files under `dir` (relative to this root) in `rev`'s tree, relative to this root.
    pub fn files_at(&self, rev: &str, dir: &Path) -> Result<Vec<std::path::PathBuf>, VcsError> {
        let dir = dir.to_string_lossy();
        let listed = self.git_stdout(&[
            "-c",
            "core.quotepath=off",
            "ls-tree",
            "-r",
            "--name-only",
            rev,
            "--",
            &dir,
        ])?;
        Ok(listed.lines().map(std::path::PathBuf::from).collect())
    }

    /// Every file under this root with one of `names` as its file name, in `rev`'s tree or on disk (tracked or
    /// untracked, not ignored), relative to this root.
    pub fn files_named(
        &self,
        rev: &str,
        names: &[&str],
    ) -> Result<std::collections::BTreeSet<std::path::PathBuf>, VcsError> {
        let at_rev = self.git_stdout(&[
            "-c",
            "core.quotepath=off",
            "ls-tree",
            "-r",
            "--name-only",
            rev,
            "--",
            ".",
        ])?;
        let on_disk = self.git_stdout(&[
            "-c",
            "core.quotepath=off",
            "ls-files",
            "--cached",
            "--others",
            "--exclude-standard",
            "--",
            ".",
        ])?;
        Ok(at_rev
            .lines()
            .chain(on_disk.lines())
            .map(std::path::PathBuf::from)
            .filter(|path| {
                path.file_name()
                    .and_then(|name| name.to_str())
                    .is_some_and(|name| names.contains(&name))
            })
            .collect())
    }

    /// Removes a worktree [`Self::add_checkpoint_worktree`] added.
    pub fn remove_worktree(&self, dir: &Path) -> Result<(), VcsError> {
        let dir = dir.to_string_lossy();
        self.git_stdout(&["worktree", "remove", "--force", &dir]).map(drop)
    }

    /// An unsigned commit of `tree` with fixed identity: it records state and is never pushed, so the user's signing
    /// key and identity play no part.
    fn internal_commit(&self, tree: &str, parents: &[&str], message: &str) -> Result<CommitSha, VcsError> {
        let mut args = vec![
            "-c",
            "user.name=Callisto",
            "-c",
            "user.email=callisto@localhost",
            "commit-tree",
            "--no-gpg-sign",
            tree,
        ];
        for parent in parents {
            args.extend(["-p", parent]);
        }
        args.extend(["-m", message]);
        let sha = self.git_stdout(&args)?;
        CommitSha::parse(&sha).map_err(|e| VcsError::InvalidCommitSha {
            context: "in `git commit-tree` output".to_string(),
            message: e.to_string(),
        })
    }

    fn git_stdout(&self, args: &[&str]) -> Result<String, VcsError> {
        self.git_stdout_env(args, &[])
    }

    fn git_stdout_env(&self, args: &[&str], env: &[(&str, &str)]) -> Result<String, VcsError> {
        let output = self.runner().run_with_env("git", args, self.root(), env)?;
        if !output.success() {
            return Err(git_failed(args, self.root(), &output.stderr));
        }
        Ok(output.stdout_trimmed().to_string())
    }
}

fn git_failed(args: &[&str], root: &Path, stderr: &str) -> VcsError {
    VcsError::Git(format!(
        "`git {}` failed in `{}`: {}",
        args.join(" "),
        root.display(),
        stderr.trim()
    ))
}

    pub fn path_exists_at(&self, rev: &str, path: &Path) -> Result<bool, VcsError> {
        let spec = format!("{rev}:./{}", path.display());
        let args = ["rev-parse", "--verify", "--quiet", &spec];
        let output = self.runner.run("git", &args, &self.root)?;
        if output.success() {
            return Ok(true);
        }
        if output.exit_code == Some(1) {
            return Ok(false);
        }
        Err(probe_failed(&args, &self.root, &output))
    }

    /// Files in `rev`'s tree matching one of `pathspecs` whose text contains `needle`, ignoring case.
    ///
    /// No match is an empty list; a revision that cannot be searched is an error.
    pub fn files_containing_at(&self, rev: &str, needle: &str, pathspecs: &[&str]) -> Result<Vec<PathBuf>, VcsError> {
        let mut args = vec!["grep", "-l", "-z", "-F", "-i", "-e", needle, rev, "--"];
        args.extend_from_slice(pathspecs);
        let output = self.runner.run("git", &args, &self.root)?;
        if output.exit_code == Some(1) {
            return Ok(Vec::new());
        }
        if !output.success() {
            return Err(probe_failed(&args, &self.root, &output));
        }
        let prefix = format!("{rev}:");
        Ok(output
            .stdout
            .split('\0')
            .filter_map(|entry| entry.strip_prefix(&prefix))
            .map(PathBuf::from)
            .collect())
    }

    /// The text of `path` (relative to this root) in `rev`'s tree, decoded lossily; `None` when it is absent.
    pub fn read_at(&self, rev: &str, path: &Path) -> Result<Option<String>, VcsError> {
        if !self.path_exists_at(rev, path)? {
            return Ok(None);
        }
        let spec = format!("{rev}:./{}", path.display());
        let args = ["show", &spec];
        let output = self.runner.run("git", &args, &self.root)?;
        if !output.success() {
            return Err(probe_failed(&args, &self.root, &output));
        }
        Ok(Some(output.stdout))
    }

    /// The most recent commit that added `path`, if it is committed.
    pub fn commit_adding(&self, path: &Path) -> Result<Option<String>, VcsError> {
        // A repository with no commits has no history to search; `git log` would fail there.
        if self.resolve_commit("HEAD")?.is_none() {
            return Ok(None);
        }
        let path = path.to_string_lossy();
        let args = [
            "log",
            "--no-show-signature",
            "--diff-filter=A",
            "--format=%H",
            "-1",
            "--",
            &path,
        ];
        let output = self.runner.run("git", &args, &self.root)?;
        if !output.success() {
            return Err(probe_failed(&args, &self.root, &output));
        }
        let sha = output.stdout_trimmed();
        Ok((!sha.is_empty()).then(|| sha.to_string()))
    }

    /// The commits on HEAD's first-parent line that changed `pathspecs`, newest first. A merge commit counts when
    /// it changes them relative to its first parent, so a squash or merge landing a release is one entry.
    pub fn first_parent_commits_touching(&self, pathspecs: &[PathBuf]) -> Result<Vec<String>, VcsError> {
        let mut args: Vec<String> = ["log", "--no-show-signature", "--first-parent", "--format=%H", "--"]
            .map(str::to_owned)
            .into();
        args.extend(pathspecs.iter().map(|path| path.to_string_lossy().into_owned()));
        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
        let output = self.runner.run("git", &arg_refs, &self.root)?;
        if !output.success() {
            return Err(probe_failed(&arg_refs, &self.root, &output));
        }
        Ok(output.stdout_lines().map(str::to_owned).collect())
    }

    /// [`Self::first_parent_commits_touching`] for many paths in one `git log`, so each path's commits cost no process
    /// of their own.
    pub fn first_parent_commits_by_path(&self, paths: &[PathBuf]) -> Result<FirstParentTouches, VcsError> {
        let mut touches = FirstParentTouches::default();
        if paths.is_empty() {
            return Ok(touches);
        }
        // `-z` keeps odd file names unquoted; `\x01` opens each commit's record, whose files follow NUL-separated.
        let mut args: Vec<String> = [
            "log",
            "--no-show-signature",
            "--first-parent",
            "-m",
            "--root",
            "-z",
            "--name-only",
            "--relative",
            "--format=%x01%H",
            "--",
        ]
        .map(str::to_owned)
        .into();
        args.extend(paths.iter().map(|path| format!(":(literal){}", path.to_string_lossy())));
        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
        let output = self.runner.run("git", &arg_refs, &self.root)?;
        if !output.success() {
            return Err(probe_failed(&arg_refs, &self.root, &output));
        }
        for record in output.stdout.split('\u{1}').skip(1) {
            let mut fields = record.split('\0');
            let Some(commit) = fields.next() else {
                continue;
            };
-----
            .collect())
    }

    /// The directory every git command runs in.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// The runner every git command goes through.
    pub fn runner(&self) -> &dyn CommandRunner {
        self.runner
    }

    /// Resolves `refname` (tag, branch, or partial/full SHA) to the commit
    /// it points at. An unresolvable ref resolves to `Ok(None)`, which
    /// callers treat as "no bound" / "infer over full history".
    pub fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
        let rev = format!("{refname}^{{commit}}");
        let args = ["rev-parse", "--verify", "--quiet", &rev];
        let output = self.runner.run("git", &args, &self.root)?;

        if output.exit_code == Some(1) {
            return Ok(None);
        }
        if !output.success() {
            return Err(probe_failed(&args, &self.root, &output));
        }
        let sha_str = output.stdout_trimmed();
        if sha_str.is_empty() {
            return Ok(None);
        }
        Ok(CommitSha::parse(sha_str).ok())
    }

    /// Lists non-merge commits reachable from `HEAD`, down to (exclusive)
    /// `since_ref` when given, keeping those that touch at least one of
    /// `pathspecs` (empty keeps every commit).
    ///
    /// `--full-history`: a commit touching a pathspec counts even when a
    /// later merge discarded its change (e.g. `merge -s ours`); default
    /// history simplification would silently drop it.
    ///
    /// A `since_ref` that is given but does not resolve is
    /// [`VcsError::RefNotFound`], never a silent unbounded walk.
    pub fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError> {
        let mut args: Vec<String> = vec![
            "log".to_string(),
            "--no-show-signature".to_string(),
            "--no-merges".to_string(),
            "--full-history".to_string(),
            format!("--format={RECORD_SEP}%H{FIELD_SEP}%B"),
        ];

        match since_ref {
            Some(r) => args.push(format!("{r}..HEAD")),
            None => args.push("HEAD".to_string()),
        }

        if !pathspecs.is_empty() {
            args.push("--".to_string());
            args.extend(pathspecs.iter().map(|p| p.display().to_string()));
        }

        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
        let output = self.runner.run("git", &arg_refs, &self.root)?;

        if !output.success() {
            if let Some(r) = since_ref
                && self.resolve_commit(r)?.is_none()
            {
                return Err(VcsError::RefNotFound {
                    ref_name: r.to_string(),
                });
            }
            if self.head_is_unborn() {
                return Ok(Vec::new());
            }
            return Err(VcsError::Git(format!(
                "`git log` failed in `{}`: {}",
                self.root.display(),
                output.redacted_stderr()
            )));
        }

        parse_git_log_output(&output.stdout, &self.root)
    }

    /// A repository with no commits yet; a damaged one must not look empty, so HEAD is not peeled.
    fn head_is_unborn(&self) -> bool {
        self.runner
            .run("git", &["rev-parse", "--verify", "--quiet", "HEAD"], &self.root)
            .is_ok_and(|output| output.exit_code == Some(1))
    }

    /// Resolves every ref in `refs` to its commit with one `git rev-parse`.
    /// `None` when any of them does not resolve.
    pub fn resolve_commits(&self, refs: &[String]) -> Result<Option<Vec<CommitSha>>, VcsError> {
        let revs: Vec<String> = refs.iter().map(|r| format!("{r}^{{commit}}")).collect();
        let mut args = vec!["rev-parse"];
        args.extend(revs.iter().map(String::as_str));
        let output = self.runner.run("git", &args, &self.root)?;
        if !output.success() {
            // The batch exits 128 for a missing ref and for a broken repository alike; one probe each tells them apart.
            for r in refs {
                if self.resolve_commit(r)?.is_none() {
                    return Ok(None);
                }
            }
            return Err(probe_failed(&args, &self.root, &output));
        }
        let shas: Option<Vec<CommitSha>> = output.stdout_lines().map(|l| CommitSha::parse(l).ok()).collect();
        Ok(shas.filter(|shas| shas.len() == refs.len()))
    }

    /// Tracked paths, relative to the root and limited to it, whose worktree
    /// contents differ from `since_ref`.
    pub fn paths_differing_from(&self, since_ref: &str) -> Result<Vec<PathBuf>, VcsError> {
        self.name_only(&[
            "diff",
            "--no-renames",
            "--relative",
            "--name-only",
            "-z",
            since_ref,
            "--",
        ])
    }

    /// Tracked paths, relative to the root and limited to it.
    pub fn tracked_paths(&self) -> Result<Vec<PathBuf>, VcsError> {
        self.name_only(&["ls-files", "-z"])
    }

    /// The object id each `<revision>:<path>` names, `None` for one that names nothing, from one `git cat-file
    /// --batch-check`. An empty path names the revision's root tree. Two specs name the same content exactly when their
    /// ids are equal, so this compares directories at two commits without reading either.
    pub fn object_ids(&self, specs: &[String]) -> Result<Vec<Option<String>>, VcsError> {
        if specs.is_empty() {
            return Ok(Vec::new());
        }
        let args = ["cat-file", "--batch-check"];
        let stdin = specs.join("\n") + "\n";
        let output = self.runner.run_with_stdin("git", &args, &self.root, stdin.as_bytes())?;
        if !output.success() {
            return Err(probe_failed(&args, &self.root, &output));
        }
        let malformed = |detail: String| VcsError::MalformedLogOutput {
            detail: format!("in `{}`: {detail}", self.root.display()),
        };
        let lines: Vec<&str> = output.stdout.lines().collect();
        if lines.len() != specs.len() {
            return Err(malformed(format!(
                "`git cat-file --batch-check` answered {} lines for {} objects",
                lines.len(),
                specs.len()
            )));
        }
        specs
            .iter()
            .zip(lines)
            .map(|(spec, line)| {
                if line.strip_prefix(spec.as_str()) == Some(" missing") {
                    return Ok(None);
                }
                match line.split(' ').next() {
                    Some(id) if CommitSha::parse(id).is_ok() => Ok(Some(id.to_owned())),
                    _ => Err(malformed(format!("`{spec}` was answered with `{line}`"))),
                }
            })
            .collect()
    }

    fn name_only(&self, args: &[&str]) -> Result<Vec<PathBuf>, VcsError> {
        let output = self.runner.run("git", args, &self.root)?;
        if !output.success() {
            return Err(VcsError::Git(format!(
                "`git {}` failed in `{}`: {}",
                args[0],
                self.root.display(),
                output.redacted_stderr()
            )));
        }
        Ok(output
            .stdout
            .split('\0')
            .map(|path| path.trim_start_matches('\n'))
            .filter(|path| !path.is_empty())
            .map(PathBuf::from)
            .collect())
    }

    /// Creates the tag `name` at `target_sha`: annotated with `message`
    /// when `Some`, lightweight when `None`. Fails if the tag already
    /// exists. Writes a ref, so it requires an [`ApplyPermit`].
    pub fn create_tag(
        &self,
        name: &str,
        target_sha: &CommitSha,
        message: Option<&str>,
        sign: TagSignPolicy,
        _permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        let identity = match message {
            Some(_) => self.tagger_identity_override(target_sha)?,
            None => None,
        };
        let mut args: Vec<&str> = Vec::new();
        if let Some([name_config, email_config]) = &identity {
            args.extend(["-c", name_config.as_str(), "-c", email_config.as_str()]);
        }
        // `--` ends option parsing so `name` can never be misread as a flag.
        args.push("tag");
        if let Some(msg) = message {
            args.extend(["-a", "-m", msg]);
        }
        if matches!(sign, TagSignPolicy::ForceUnsigned) {
            args.push("--no-sign");
        }
        args.extend(["--", name, target_sha.as_str()]);
        let output = self.runner.run("git", &args, &self.root)?;
        if !output.success() {
            return Err(VcsError::Git(format!(
                "`git tag` failed in `{}`: {}",
                self.root.display(),
                output.redacted_stderr()
            )));
        }
        Ok(())
    }

    /// `None` when Git can resolve a committer identity itself. Otherwise the
    /// target commit's committer, as `-c` overrides, since an annotated tag
    /// needs a tagger and a release runner's checkout often configures none.
    fn tagger_identity_override(&self, target_sha: &CommitSha) -> Result<Option<[String; 2]>, VcsError> {
        let ident = self.runner.run("git", &["var", "GIT_COMMITTER_IDENT"], &self.root)?;
        if ident.success() {
            return Ok(None);
        }
        let commit = self
            .runner
            .run("git", &["cat-file", "commit", target_sha.as_str()], &self.root)?;
        let committer = commit
            .stdout
            .lines()
            .take_while(|line| !line.is_empty())
            .find_map(|line| line.strip_prefix("committer "))
            .and_then(|ident| ident.split_once(" <"))
            .and_then(|(name, rest)| Some((name, rest.split_once('>')?.0)));
        match committer {
            Some((name, email)) if commit.success() && !name.is_empty() && !email.is_empty() => {
                Ok(Some([format!("user.name={name}"), format!("user.email={email}")]))
            }
            _ => Err(VcsError::Git(format!(
                "no Git identity for the tagger and could not read the committer of `{}`: {}",
                target_sha.as_str(),
                commit.redacted_stderr()
            ))),
        }
    }
}

/// Parses the `<RECORD_SEP>%H<FIELD_SEP>%B`-formatted `git log` output
/// produced by [`GitAccess::commits_since`] into [`GitCommit`]s, splitting
/// each raw message on its first blank line into `summary`/`body`.
fn parse_git_log_output(stdout: &str, cwd: &Path) -> Result<Vec<GitCommit>, VcsError> {
    let mut commits = Vec::new();

    for record in stdout.split(RECORD_SEP) {
        // `--format=` output without a `format:`/`tformat:` prefix ends each entry with a newline;
        // strip it, not the message's own content.
        let record = record.trim_end_matches('\n');
        if record.is_empty() {
            continue;
        }

        let Some((sha_str, message)) = record.split_once(FIELD_SEP) else {
            return Err(VcsError::MalformedLogOutput {
                detail: format!(
                    "in `{}`: expected a `<sha>{FIELD_SEP:?}<message>` record, got: {record:?}",
                    cwd.display()
                ),
            });
        };

        let sha = CommitSha::parse(sha_str).map_err(|e| VcsError::InvalidCommitSha {
            context: format!("in `git log` output in `{}`", cwd.display()),
            message: e.to_string(),
        })?;

        let message = message.replace("\r\n", "\n");
        let (summary, body) = match message.split_once("\n\n") {
            Some((title, rest)) => (title.trim_end().to_string(), Some(rest.to_string())),
            None => (message.trim_end().to_string(), None),
        };

        commits.push(GitCommit { sha, summary, body });
    }

    Ok(commits)
}

