45	/// The pull request number in a commit subject: `Merge pull request #12 from ...` or `Title (#12)`.
46	fn pull_request_of(subject: &str) -> Option<u64> {
47	    if let Some(rest) = subject.strip_prefix("Merge pull request #") {
48	        return rest.split_whitespace().next()?.parse().ok();
49	    }
50	    let tail = subject.trim_end().strip_suffix(')')?;
51	    tail.rsplit_once("(#")?.1.parse().ok()
