54	fn parse_changeset_prs(log: &str) -> BTreeMap<String, u64> {
55	    let mut found = BTreeMap::new();
56	    for block in log.split(COMMIT_MARK).skip(1) {
57	        let mut lines = block.lines();
58	        let Some(pr) = lines.next().and_then(pull_request_of) else {
59	            continue;
60	        };
61	        for path in lines.filter(|line| !line.is_empty()) {
62	            // A changeset is known by its id, the file name without `.md`. The log is newest first and a released
63	            // changeset's name can be reused, so the first addition seen is the file that exists now.
64	            if let Some(id) = Path::new(path).file_stem().and_then(|stem| stem.to_str()) {
65	                found.entry(id.to_owned()).or_insert(pr);
66	            }
67	        }
68	    }
69	    found
70	}
