124	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run);
125	
126	    // Derived before any write so an invalid plan fails early; written only after apply succeeds.
127	    let pending_decision = if !has_errors {
128	        match args.emit_decision.as_deref() {
129	            Some(path) => {
