131	                // Workspace-root-relative, not cwd-relative, so `git add -A` and a later `--decision` `git show` agree.
132	                let relative = workspace_decision_path(path, &ws.root)?;
133	                Some((ws.root.join(relative), decision))
134	            }
135	            None => None,
136	        }
137	    } else {
138	        None
139	    };
140	
141	    // Built from the plan before apply consumes the changesets it describes.
142	    let pending_preview = match args.emit_preview.as_deref().filter(|_| !has_errors) {
143	        Some(path) => Some((
144	            global.resolve_file_arg(path),
145	            callisto_graph::release_preview::build_release_preview_in(plan_ws, &plan)?,
146	        )),
147	        None => None,
148	    };
