150	    // A resume must start from the checkpoint plus some of the interrupted run's own writes. The plan is applied in the
151	    // checkpoint's scratch worktree to learn what a finished run leaves, which takes the run's own permit and writes
152	    // only there; a dry run has no permit, so it reports the plan without verifying the inputs.
153	    if let (Some(scratch), Some(checkpoint), Some(facts), Some(permit), false) =
154	        (&checkpoint_ws, &checkpoint, &facts, permit.as_ref(), has_errors)
155	    {
156	        let changes =
157	            callisto_graph::commands::resume_input_changes(&ws, scratch, checkpoint, facts, &plan, &runner, permit)?;
158	        if !changes.is_empty() {
159	            return Err(GraphError::CheckpointInputsChanged { changes }.into());
160	        }
161	    }
162	
163	    // The plan is in memory, so the checkpoint's worktree has done its job.
164	    drop(checkpoint_ws);
165	    drop(resume_tree);
166	
167	    let apply_opts = ApplyOptions {
168	        refresh_lockfiles: !args.no_refresh_lockfiles,
169	        transient: false,
170	    };
171	
172	    let applying = !has_errors && permit.is_some();
173	    // A plan that writes nothing has nothing to resume or discard.
174	    let writes = !callisto_graph::apply::written_paths(&plan).is_empty();
175	    if let (true, true, None, Some(facts), Some(permit)) = (applying, writes, &checkpoint, &facts, permit.as_ref()) {
176	        // A run that cannot start must leave no checkpoint behind, or the fix its error asks for is never honoured.
177	        callisto_graph::apply::validate_plan(&ws.root, &plan, &apply_opts, permit, &runner)?;
178	        git.create_checkpoint(VERSION_CHECKPOINT, facts, &date)
179	            .map_err(GraphError::from)?;
180	    }
181	
182	    let outcome = if has_errors {
183	        ApplyOutcome::default()
184	    } else {
185	        match permit.as_ref() {
186	            Some(permit) => apply_version_plan(&ws.root, &plan, &runner, &apply_opts, permit)?,
187	            None => ApplyOutcome::default(),
188	        }
189	    };
190	
191	    if let (Some((full_path, decision)), Some(permit)) = (pending_decision.as_ref(), permit.as_ref()) {
192	        let content = serde_json::to_string_pretty(decision).expect("release decision serializes") + "\n";
193	        callisto_model::atomic::atomic_write(full_path, &content, permit).map_err(|source| CliError::Io {
194	            source,
195	            path: Some(full_path.clone()),
196	        })?;
197	    }
198	
199	    if let (Some((full_path, preview)), Some(permit)) = (pending_preview.as_ref(), permit.as_ref()) {
200	        let content = serde_json::to_string_pretty(preview).expect("release preview serializes") + "\n";
201	        callisto_model::atomic::atomic_write(full_path, &content, permit).map_err(|source| CliError::Io {
202	            source,
203	            path: Some(full_path.clone()),
204	        })?;
205	    }
206	
207	    // Every effect, the emitted files included, has landed: the run is complete.
208	    if applying && facts.is_some() {
209	        git.delete_checkpoint(VERSION_CHECKPOINT).map_err(GraphError::from)?;
210	    }
211	
212	    let report = plan.to_report(&ws.report_ids(), outcome.lockfile_refresh_results);
213	
214	    if global.dry_run && global.format == OutputFormat::Text {
215	        emit_line("[DRY-RUN] Version Plan Calculated (no files modified):")?;
216	    }
217	
218	    match global.format {
219	        OutputFormat::Json => emit_report(&mut std::io::stdout(), &report, global.dry_run)?,
220	        OutputFormat::Text => render::render_version(&report, &ws.config, &mut std::io::stdout())?,
221	    }
222	
223	    // Mirrors the pattern in status.rs: diagnostics ride in the report so the
224	    // caller sees full detail before the non-zero exit.
225	    if has_errors {
226	        Ok(ExitCode::FAILURE)
227	    } else {
228	        Ok(ExitCode::SUCCESS)
229	    }
230	}
