232	/// Today's UTC date as `YYYY-MM-DD`.
233	fn today_utc() -> String {
234	    let seconds = std::time::SystemTime::now()
235	        .duration_since(std::time::UNIX_EPOCH)
236	        .map_or(0, |elapsed| elapsed.as_secs());
237	    utc_date(i64::try_from(seconds / 86_400).unwrap_or(0))
238	}
