240	/// Howard Hinnant's civil-from-days: the proleptic Gregorian date of a day count since 1970-01-01.
241	fn utc_date(days: i64) -> String {
242	    let z = days + 719_468;
243	    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
244	    let day_of_era = z - era * 146_097;
245	    let year_of_era = (day_of_era - day_of_era / 1_460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
246	    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
247	    let shifted_month = (5 * day_of_year + 2) / 153;
248	    let day = day_of_year - (153 * shifted_month + 2) / 5 + 1;
249	    let month = if shifted_month < 10 {
250	        shifted_month + 3
251	    } else {
252	        shifted_month - 9
253	    };
254	    let year = year_of_era + era * 400 + i64::from(month <= 2);
255	    format!("{year:04}-{month:02}-{day:02}")
256	}
