179	/// Every file outside `.git`, plus the status and the index, so two trees compare exactly.
180	fn state(root: &Path) -> (BTreeMap<PathBuf, Vec<u8>>, String, String) {
181	    fn walk(dir: &Path, root: &Path, files: &mut BTreeMap<PathBuf, Vec<u8>>) {
182	        for entry in fs::read_dir(dir).unwrap().flatten() {
183	            let path = entry.path();
184	            if path.file_name().is_some_and(|name| name == ".git") {
185	                continue;
186	            }
187	            if path.is_dir() {
188	                walk(&path, root, files);
189	            } else {
190	                files.insert(
191	                    path.strip_prefix(root).unwrap().to_path_buf(),
192	                    fs::read(&path).unwrap_or_default(),
193	                );
194	            }
195	        }
196	    }
197	    let mut files = BTreeMap::new();
198	    walk(root, root, &mut files);
199	    (
200	        files,
201	        git(root, &["status", "--porcelain"]),
202	        git(root, &["diff", "--cached"]),
203	    )
204	}
